<script setup lang="ts">
import {computed,ref} from 'vue'
import {ArrowRight,BookOpen,Calculator,CheckCircle2} from 'lucide-vue-next'
import {formatNumber} from '../utils/format'
const change=ref(-1),side=ref<'LONG'|'SHORT'>('LONG')
const example={price:100,multiplier:10,lots:1,marginRate:.2}
const notional=example.price*example.multiplier*example.lots
const margin=notional*example.marginRate
const pnl=computed(()=>notional*change.value/100*(side.value==='LONG'?1:-1))
const terms=[
  {title:'期货是什么',body:'期货是标准化合约，约定未来按规则交收标的。浏览行情不等于参与交易；不同合约的单位、到期安排和参与要求可能不同。'},
  {title:'主力连续与实际合约',body:'主力连续把不同时期的代表性合约价格串起来，便于观察走势。它不是一个能直接下单的交割合约；实际合约有明确代码和月份。'},
  {title:'做多与做空',body:'忽略费用时，做多通常在价格上涨时获利、下跌时亏损；做空则相反。两个方向都可能亏损。'},
  {title:'合约乘数与手数',body:'报价不等于交易金额。合约乘数说明一个报价单位对应的合约规模，手数表示合约数量，两者一起影响价格变动对应的金额。'},
  {title:'保证金与杠杆',body:'保证金是履约担保，占用一部分资金不代表风险只限于这部分。较小的价格波动也可能造成较大的资金变化，亏损可能超过初始保证金。'},
  {title:'成交量与持仓量',body:'成交量描述一段时间内成交的合约手数；持仓量描述尚未了结的合约数量。它们是观察活跃程度的线索，不能直接当作资金净流入。'},
  {title:'止损为什么不等于保证',body:'止损是控制风险的安排，但能否成交及成交价格取决于市场。跳空、涨跌停或流动性不足时，实际损失可能超过计划。'},
  {title:'回撤与回测',body:'回撤描述资金从过去高点向下的幅度；回测是在历史数据和成交假设上进行仿真。历史收益和历史胜率不能直接当成未来表现。'},
  {title:'模型分数与胜率',body:'模型分数是规则汇总的结果，证据覆盖率描述输入是否齐全。未经独立校准，二者都不能解释成未来盈利概率。'},
  {title:'实时、缓存与降级',body:'先读观测时间和来源。缓存保留过去的有效快照，降级说明主通道异常或使用了替代来源；它们都不等于当前可成交报价。'},
]
const questions=[
  {title:'保证金占用较少，是否意味着最多只亏这笔保证金？',options:['是，只会亏掉保证金','不是，实际亏损可能更大'],correct:1,explanation:'保证金是担保要求，不是最大亏损承诺。还需要理解追加保证金、强平和市场成交风险。'},
  {title:'看到主力连续报价后，可以直接按这个代码交易吗？',options:['应先确认实际合约、规格和月份','可以，连续报价就是实际合约'],correct:0,explanation:'连续序列用于观察。进入实际交易前，需要确认具体交割合约与规则，避免把换月后的序列当成同一张合约。'},
  {title:'一份回测历史胜率为60%，是否就能认定下一笔有60%盈利概率？',options:['不能，需要独立验证与概率校准','能，历史胜率就是下一笔的概率'],correct:0,explanation:'回测区间、交易成本、样本选择和市场变化都会影响结果。历史统计不是下一笔交易的概率保证。'},
]
const answers=ref<(number|null)[]>(questions.map(()=>null))
const answered=computed(()=>answers.value.filter(v=>v!==null).length)
</script>

<template>
  <div class="page-stack learning-page">
    <section class="learning-hero"><div><span class="eyebrow">不必先懂所有术语</span><h2>先看懂，再练习。</h2><p>你可以只了解市场、阅读资讯，也可以逐步学习研究工具。平台不会因为完成学习就替你开启交易。</p><div class="hero-links"><RouterLink to="/market">先浏览行情 <ArrowRight :size="14"/></RouterLink><a href="#terms">查一个术语</a></div></div><BookOpen :size="62"/></section>
    <section class="learning-steps" aria-label="入门路径"><RouterLink to="/market"><b>01</b><h3>看市场</h3><p>选择熟悉的行业，观察不同品种的价格变化与数据时间。</p></RouterLink><a href="#example"><b>02</b><h3>理解金额与风险</h3><p>用一个虚构例子，区分报价、合约金额、保证金与盈亏。</p></a><RouterLink to="/paper"><b>03</b><h3>用虚拟资金练习</h3><p>自行创建模拟环境，了解下单、费用和持仓变化。</p></RouterLink><RouterLink to="/strategy"><b>04</b><h3>再了解研究方法</h3><p>比较不同规则的依据，练习回测与复盘，不追逐分数。</p></RouterLink></section>
    <section id="example" class="lesson-panel"><header><Calculator :size="19"/><div><h2>报价变动，为什么会影响更多资金？</h2><p>以下是虚构合约的数学示例，不代表任何真实品种的规格或保证金要求。</p></div></header><div class="example-layout"><div class="example-controls"><p>假设：价格 <b>100</b>，合约乘数 <b>10</b>，持有 <b>1手</b>，示例保证金率 <b>20%</b>。</p><label>示例持仓方向<select v-model="side"><option value="LONG">做多：价格上涨时有利</option><option value="SHORT">做空：价格下跌时有利</option></select></label><label>价格变化：{{change>0?'+':''}}{{change}}%<input v-model.number="change" aria-label="示例价格变化" type="range" min="-5" max="5" step="1"/></label><span>拖动滑块，对比同样的价格变化。</span></div><div class="example-output" aria-live="polite"><div><span>合约名义金额</span><strong>{{formatNumber(notional)}} 元</strong><small>100 × 10 × 1</small></div><div><span>示例保证金占用</span><strong>{{formatNumber(margin)}} 元</strong><small>{{notional}} × 20%</small></div><div><span>忽略费用的盈亏变化</span><strong :class="pnl>=0?'positive':'negative'">{{pnl>=0?'+':''}}{{formatNumber(pnl)}} 元</strong><small>相当于示例保证金的 {{formatNumber(pnl/margin*100,1)}}%</small></div></div></div><p class="lesson-note">盈亏金额由合约规模与价格变动决定，不会因为占用保证金较少就自动变小。此例忽略手续费、滑点及保证金调整；真实风险还取决于市场与账户情况。</p></section>
    <section id="terms" class="lesson-panel"><header><BookOpen :size="19"/><div><h2>把常见术语翻译成日常语言</h2><p>按需展开，不需要一次读完。</p></div></header><div class="terms-grid"><details v-for="term in terms" :key="term.title"><summary>{{term.title}}</summary><p>{{term.body}}</p></details></div></section>
    <section class="lesson-panel"><header><CheckCircle2 :size="19"/><div><h2>三个问题，检查自己有没有理解</h2><p>已回答 {{answered}} / {{questions.length}}。这只是学习练习，不是投资适当性或实盘资格评估。</p></div></header><div class="quiz-grid"><article v-for="(question,index) in questions" :key="question.title"><h3>{{index+1}}. {{question.title}}</h3><button v-for="(option,answer) in question.options" :key="option" type="button" :aria-pressed="answers[index]===answer" @click="answers[index]=answer">{{option}}</button><p v-if="answers[index]!==null" :class="answers[index]===question.correct?'understood':'revisit'">{{answers[index]===question.correct?'理解正确。':'再想一想。'}}{{question.explanation}}</p></article></div></section>
    <footer class="learning-sources"><strong>继续阅读官方投教资料</strong><a href="https://edu.cfachina.org/" target="_blank" rel="noopener noreferrer">中国期货业协会 · 投资者教育 ↗</a><a href="https://www.cfachina.org/governmentrules/selfdisciplinerules/businessspecificationclass/202101/t20210125_15136.html" target="_blank" rel="noopener noreferrer">中国期货业协会 · 期货交易风险揭示 ↗</a><a href="https://www.cftc.gov/zh-hans/LearnAndProtect/AdvisoriesAndArticles/economicpurpose.html" target="_blank" rel="noopener noreferrer">CFTC · 期货市场如何运作 ↗</a><p>本站说明帮助理解产品与数据；实际合约规则、参与要求和风险揭示应以交易所、期货公司及监管机构的正式资料为准。</p></footer>
  </div>
</template>

